import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, PointLight } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Build Card Panel (512x320 aspect ratio -> 1.6 x 1.0 unit plane)
  const width = 1.6;
  const height = 1.0;
  const cardGeo = new PlaneGeometry(width, height);

  // Gradient Material with TSL
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.5,
    transparent: true,
    opacity: 0.95
  });

  // Engineered gradient color from surface (#0b0b10) to ink (#16161d)
  const colorBottom = vec3(0.043, 0.043, 0.063); // #0b0b10
  const colorTop = vec3(0.086, 0.086, 0.114);    // #16161d
  cardMat.colorNode = mix(colorBottom, colorTop, uv().y);

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Load brushed-metal texture mapping if available
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    if (tex) {
      tex.colorSpace = 'srgb';
      cardMat.roughnessMap = tex;
      cardMat.metalnessMap = tex;
      cardMat.needsUpdate = true;
    }
  }).catch(() => {});

  // Red accent indicator strip (signal red, ≤10% of frame)
  const accentGeo = new PlaneGeometry(0.03, 0.6);
  const accentMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 0.8
  });
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(-0.65, 0, 0.005);
  group.add(accentStrip);

  // Dynamic subtle local rim light to make the brushed metal texture pop
  const localLight = new PointLight(colors.accent, 0.8, 3.0);
  localLight.position.set(-1.0, 1.0, 0.5);
  group.add(localLight);

  // Text Content (Journal 1)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textVal = items[0]?.text ?? "Journal 1";

  const titleText = ctx.fontAtlas.createText(textVal, {
    fontSize: 39,
    color: colors.paper,
    align: 'left'
  });
  // Adjust position and scale within scene bounds
  titleText.position.set(-0.5, -0.05, 0.01);
  titleText.scale.setScalar(0.0035);
  group.add(titleText);

  // Unifying subtle floating animation
  const tl = gsap.timeline({ repeat: -1, yoyo: true });
  tl.to(group.position, {
    y: '+=0.02',
    duration: 3,
    ease: 'power1.inOut'
  });

  // Cleanup handler
  group.userData = {
    cleanup() {
      tl.kill();
      cardGeo.dispose();
      cardMat.dispose();
      accentGeo.dispose();
      accentMat.dispose();
    }
  };

  return group;
}
